{
  "гриб": "Красный мухомор (Amanita muscaria)",
  "состав": [
    {
      "вещество": "Изоглутаминовая кислота (ibotenic acid)",
      "содержание": "0,1–0,4 % от сухого веса",
      "влияние": "Нейротоксин, агонист NMDA-рецепторов, вызывает спутанность сознания, судороги и галлюцинации."
    },
    {
      "вещество": "Муцимол (muscimol)",
      "содержание": "0,2–0,7 % от сухого веса",
      "влияние": "Агонист GABA_A-рецепторов, действует как седативное и снотворное средство с лёгким анксиолитическим эффектом."
    },
    {
      "вещество": "Муказаон (muscazone, N-метилмуцимол)",
      "содержание": "0,05–0,1 % от сухого веса",
      "влияние": "Метаболит муцимола с меньшей аффинностью к GABA_A-рецепторам; обладает умеренным нейротропным действием."
    },
    {
      "вещество": "Мукарин (muscarine)",
      "содержание": "< 0,01 % от сухого веса (следы)",
      "влияние": "Паразимпатомиметик: усиливает секрецию, замедляет сердцебиение, сужает зрачки."
    },
    {
      "вещество": "Муцин (muscine)",
      "содержание": "неизвестно",
      "влияние": "Пептид с GABA-подобной активностью, способен оказывать нейротоксическое и спазмолитическое действие."
    },
    {
      "вещество": "Склеросант (sclerosant)",
      "содержание": "неизвестно",
      "влияние": "Циклический аналог муцимола, проявляет умеренную GABA-миметическую активность."
    }
  ]
}

{
  "гриб": "Amanita citrina (лимонный мухомор)",
  "состав": [
    {
      "вещество": "иботеновая кислота",
      "содержание": "~2–5 % от сухого веса",
      "влияние": "Нейротоксин, агонист NMDA-рецепторов, вызывает судороги, тахикардию и спутанность сознания."
    },
    {
      "вещество": "мусцимол",
      "содержание": "~1–3 % от сухого веса",
      "влияние": "Агонист ГАМК-A рецепторов, вызывает седацию, миоз, брадикардию и галлюцинации."
    },
    {
      "вещество": "мускарин",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Холергический агонист, усиливает слюнотечение, потливость и сужение зрачков."
    },
    {
      "вещество": "булатарен",
      "содержание": "неизвестно (мг/кг)",
      "влияние": "Сескитерпеноид с лёгким противовоспалительным и гипотензивным действием."
    },
    {
      "вещество": "α-аманицин",
      "содержание": "отсутствует (или < 0,01 % от сухого веса)",
      "влияние": "При наличии ингибирует РНК-полимеразу II и вызывает печёночный некроз; в A. citrina клинически не значим."
    }
  ]
}

{
  "гриб": "Amanita rubescens (мухомор серо-розовый)",
  "состав": [
    {
      "вещество": "Токсичный теплолабильный гликопротеин (рубросцеин)",
      "содержание": "~1–3 % от сухого веса",
      "влияние": "Вызывает аллергические реакции и gastroинтестинальный токсикоз; разрушается при длительной термической обработке."
    },
    {
      "вещество": "Мускарин",
      "содержание": "неизвестно (следовые количества, существенно меньше, чем у A. muscaria)",
      "влияние": "Агонист мускариновых холинергических рецепторов, вызывает слюнотечение, потливость, брадикардию, спазм бронхов."
    },
    {
      "вещество": "Хитин",
      "содержание": "~2–5 % от сухого веса",
      "влияние": "Структурный полисахарид клеточных стенок гриба; для человека практически не усваивается и может раздражать ЖКТ."
    },
    {
      "вещество": "Грибной гликоген",
      "содержание": "~5–10 % от сухого веса",
      "влияние": "Полная полимерная форма глюкозы; после термической обработки усваивается как обычный полисахарид."
    },
    {
      "вещество": "Белки (аминокислоты)",
      "содержание": "~20–30 % от сухого веса",
      "влияние": "Источники пищевых белков; содержат эссенциальные аминокислоты, но при сырой дегустации могут участвовать в аллергической реакции."
    },
    {
      "вещество": "Бета-глюканы (хитозан, глюкан)",
      "содержание": "неизвестно",
      "влияние": "Иммуномодулирующие полисахариды; в больших дозах могут вызывать слабые аллергические проявления у предрасположенных лиц."
    }
  ]
}
